"""Explicit bench instructions for the MVP adaptations of ETF Projects 1–4.

One required baseline product precedes bounded redesign. checks.json contains
independent transfer problems, not dimensions to substitute into the build.
No student records are stored here. Builds require a teacher equipment rehearsal.
"""
import json
from pathlib import Path

PROJECTS=[
 dict(name='Build a Stand and Three-Bay Organizer',source='ETF Project 1 · product design, prototyping and revision',goal='Build a card stand, then a three-bay supply tray; measure fit and improve one tested feature.',materials='Folders/card, scissors, tape, rulers/tape measures and pocket notebooks; clean thin packaging card for the durable tray.',prep='For 15 students use six pairs and one trio: seven crew trays. Every student measures and draws; rotate marker, cutter and checker. The trio rotates all three roles. Rehearse the specified build before teaching; the directions are authored construction plans, not a claim of physical validation.',count=6),
 dict(name='Build and Test a Model Community Room',source='ETF Project 2 · structures, scale drawings and the building envelope',goal='Build the supplied 16 × 12-ft community room at 1/2 in = 1 ft, with a working door and removable roof. Test structural shapes and insulation.',materials='Paper, folders, thin packaging card, tape, scissors, books, paper clips; later matching cups, ice, trays, a timer and a 1-g balance.',prep='Use seven crew trays. Reserve a permitted classroom survey area. Collect the daily kits before release. Keep the supplied model dimensions separate from actual school measurements. These are classroom models, not full-size construction designs.',count=10),
 dict(name='Build a Syringe-Powered Delivery Sled',source='ETF Project 3 · fluid motion, fabrication, diagnosis and measured redesign',goal='Build one water-powered delivery sled: a hand syringe moves a second syringe and an attached card sled along a marked track.',materials='Per crew: two matching 20-mL needleless slip-tip syringes, 60 cm of compatible flexible clear tubing, water tray, 12 × 6-in card base and folder card. Shared prepared gravity-flow station.',prep='Use seven matched syringe pairs and seven 60-cm tubes. Verify leak-free tube fit, easy hand travel and at least 20 mm usable stroke. Prepare the water pairs at input 15 mL/output 5 mL with a water-filled tube. Connect below the tray waterline to exclude air; wipe dry and check operation. No needles or heat. This course uses the syringe device throughout; a boat is not an alternative students must choose.',count=9),
 dict(name='Wire a Door Signal and Two-Room Lighting',source='ETF Project 4 · electrical control, measurement and diagnosis',goal='Build a 3-V door-open signal and two-room model with independently switched lamps. Trace, test and repair the actual connections.',materials='Per crew: switched two-AA holder with cells (3 V nominal), two 3-V miniature incandescent lamps in holders, two SPST switches, ten insulated alligator leads, wooden spring clothespin, foil and card. Shared digital multimeter with intact fused current input.',prep='Obtain seven complete kits and test one two-lamp parallel circuit with the chosen holder before release. Use 3-V-rated miniature filament lamps; bare LEDs are not substitutes for this recipe. Maximum classroom supply is two AA cells in the specified holder. Label lamp terminals A/B, switches 1/2, and supply +/−. Prepare one supervised meter station and label its actual sockets/range; use the instrument manual. Do not release meter lessons without that station.',count=11),
]
CHECKS=json.loads((Path(__file__).parent/'checks.json').read_text())
DAYS=[]
COMMON='Each student: tape measure, pencil and graph notebook. Per crew: ruler, scissors and masking tape. '
TRAY='B = base 8 × 6 in; F and R = two long walls 8 × 2 in; E1, E2, D1 and D2 = four short-wall blanks 6 × 2 in. Trim short walls to the measured gap between F and R. '
ROOM='Base 8 × 6 in; N/S walls 8 × 4 in; E/W blanks 6 × 4 in (trim to fit between N/S); roof 8 × 6 in. South door: left jamb 1 in from west end, opening 1 1/2 in wide × 3 1/2 in high. '
SLED='12 × 6-in base; output nozzle at x = 3 in on centerline y = 3 in; two 4 × 1-in card saddle strips; sled blank 3 × 2 in, folded 1 in from one short end. '

def add(p,title,product,diagram,why,kit,read,measure,plan,build,test,done,prep,demo,look,trouble):
 c=CHECKS[len(DAYS)]
 assert c['project']==p
 DAYS.append(dict(**c,title=title,product=product,diagram=diagram,why=why,kit=COMMON+kit,read=read,measure=measure,plan=plan,build=build,test=test,done=done,prep=prep,demo=demo,look=look,trouble=trouble))

add(1,'Build a Stand for an Instruction Card',
 'Make one triangular stand for a 3 × 5-in card, then improve its card-supporting lip. The 5-in card edge rests horizontally on the 4-in-wide stand.', 'stand',
 'A technician must turn a flat pattern into a useful object. Today you will read a cut/fold plan, measure fractions from one datum and check whether the product works.',
 'Two folder-card rectangles at least 10 1/2 × 4 in, one 4 × 1-in lip blank, one 4 × 1 1/2-in replacement lip blank, one paper/card rectangle 3 × 5 in, and 24 in of tape. Keep unused stock for a remake.',
 'Drawing A labels the flat panels F (front), R (rear), B (base), T (joining tab) and L (separate lip). Solid outside lines are cut edges; dashed lines are folds. The finished side view shows B flat on the table.',
 ['Cut the test card to 3 × 5 in. Mark its 5-in edge BOTTOM. The load today is this card.',
  'On the body stock, choose the left 4-in edge as datum A. Mark 0, 3, 6, 10 and 10 1/2 in along BOTH long edges, always measuring from A.',
  'Join matching marks with straight lines. Check overall width 4 in and length 10 1/2 in with your partner; then swap who reads the tape.'],
 ['Label F between 0–3 in, R between 3–6, B between 6–10, and T between 10–10 1/2. Do not cut the three inside lines.',
  'Sketch the finished triangular side view in your notebook: two 3-in sloping faces and a 4-in base. Add the 1/2-in overlap tab on a separate detail.'],
 ['Cut the OUTSIDE of the 10 1/2 × 4-in blank. Write your crew name on B.',
  'Fold at 3, 6 and 10 in, all toward the same side of the card. Press the creases against a ruler; do not cut or score with a blade.',
  'Place B flat on the desk. Bring the free edge of F to the fold between B and T. The 3-in faces meet at the top; the cross-section is a triangle.',
  'Put T inside F, overlapping it by 1/2 in. Tape the seam across the full 4-in width. The tab is a joint, not a fourth side.',
  'Cut L to 4 × 1 in. Draw and fold a line along its length, making two 4 × 1/2-in halves.',
  'Tape one half of L to F at the bottom of the front face, with the lip fold at the front/base corner. Leave the other half projecting forward as a shelf; adjust that shelf approximately level with the tabletop.',
  'Rest the card’s BOTTOM edge on L and lean the card back against F. Center it: about 1/2 in of card extends beyond each side of the stand.',
  'Run the first three-trial test. Then cut a second lip 4 × 1 1/2 in; fold 1/2 in from one long edge. Replace L, attaching the 1/2-in half to F so the shelf is now 1 in deep. Label the new lip revision B.',
  'Repeat the identical test. Keep the better lip on the stand; retain the removed lip with your notebook. If the body failed, remake it to the original dimensions before comparing lips.'],
 ['Trial: put the stand on a level desk, place the card, remove both hands and time 10 seconds. Pass only if both stand and card stay upright. Remove the card; repeat for three trials.',
  'Do three trials for the 1/2-in lip, then three for the 1-in lip. Record each pass/fail; a tie is a valid result.',
  'Measure F and B along their fold-to-fold edges. Classroom layout check: 3 in and 4 in, each within ±1/8 in. Correct a wrong fold even if the card happens to stand.'],
 ['One labeled triangular stand with a 3 × 5-in card; the spare lip beside it.', 'Notebook: labeled side view, actual F/B lengths, and a two-row table: lip depth | trial 1 | trial 2 | trial 3. Save the individual transfer answer in the app.'],
 'Set out seven kits, 15 notebooks and seven printed A sheets. Prebuild one finished sample and one unfolded labeled blank. Use 10 1/2-in stock, not a 10-in strip. A normal opened folder supplies the length.',
 'Say: “We are making THIS card stand. The 4-in panel goes on the table.” Show the completed sample before the flat plan. Model one mark from datum A, form the triangular loop, then show where T overlaps F and where L attaches. Release cutting only after both long edges have matching fold marks.',
 'At minute 25 inspect 3/6/10-in marks. At minute 40 each student points to F/R/B/T on the blank. By minute 70 expect a standing triangle; by 95 expect six recorded trials. Ask each student to show the zero reference and read one fraction without a partner.',
 'Four-sided loop → T was treated as a panel; overlap it inside F. Card slides → shelf must project below the card, not be taped flat against F. Stand rocks → straighten the seam and check B is the 4-in panel. No apparent improvement → record the tie; do not invent a failure.')

add(1,'Mock Up a Three-Bay Supply Tray','Build a folder-card tray with three side-by-side bays for erasers, binder clips and paper clips. Keep this version for comparison.','organizer',
 'Storage fit depends on inside clearance, not just outside size. This prototype gives us a real fit problem to measure before using stronger material.',
 'Folder card for the seven parts in drawing B; two erasers, three binder clips and six paper clips; 36 in of tape. '+TRAY,
 'B shows a top view and assembly. F/R run the full 8-in width. E1/E2 fit BETWEEN them. D1/D2 run front-to-back. The 1/8-in thickness and 2 1/2-in clear bays on the example are supplied math values; measure the actual folder version.',
 ['Measure the three types of supplies at their widest point. Make a table: item | width | unit.', 'Mark the base 8 × 6 in. From its left edge, mark lines at 2 5/8 and 5 1/4 in across the base; these locate the LEFT faces of D1 and D2.'],
 ['Draw an 8 × 6-in top view. Label the front edge F and the left outer edge datum A.', 'Copy the seven-part list. Assign left bay = erasers, middle = binder clips, right = paper clips. This is the required first arrangement.'],
 ['Cut B, F and R to their labeled sizes. Cut E1/E2/D1/D2 initially as 6 × 2-in rectangles.', 'Stand F and R on TOP of B, with their outside faces flush to its front and rear edges. Tape each wall to B inside and outside; keep walls upright.', 'Set E1 between F and R at the left edge. Mark the actual inside gap on E1; trim to that mark so it fits without bending F/R. Use it to mark the other three short walls, then check each fit.', 'Tape E1/E2 upright with outside faces flush to the left/right edges of B.', 'Tape D1/D2 upright with their LEFT faces on the two base lines. Tape both ends to F/R and bottom edges to B.', 'Put the assigned supplies in their bays. Partner removes and returns each type three times while the tray stays on the desk.', 'Circle one snag on your notebook top view. Write one specific proposed repair: loose joint → reinforce; object catches divider → move that divider 1/4 in. Keep the prototype intact for day 3.'],
 ['Each type fits its assigned bay and can be removed without lifting the tray. Record three attempts for each type.', 'Measure each clear bay between wall faces at the front and rear. Record the six readings, even if they are unequal.'],
 ['One three-bay folder tray with seven labeled parts and the supplies in it.', 'Notebook: top view, six clearance readings, retrieval results and one circled problem.'],
 'Provide ordinary folder stock and identical test supplies in all seven kits. Cut a sample short wall to show fitting between F/R. Do not substitute a free-choice organizer brief.',
 'Show why a 6-in short-wall blank must be trimmed when long walls occupy part of the 6-in base. Demonstrate dry fitting, marking and trimming one end. Point to “outside” and “clear” on the real tray.',
 'Check F/R sit on the base, partitions run front-to-back, and all students can identify the same datum. Accept small unequal bays for thin stock; the 2 1/2-in example assumes 1/8-in stock.',
 'Walls bow → the short pieces are too long; dry-fit and trim. Bay narrows toward rear → divider is angled; retape square to F. Supplies snag → mark the actual contact, not a vague “bad fit.”')

add(1,'Measure and Cut the Durable Tray Parts','Make the seven fitted parts for a stronger copy of the same three-bay tray; dry-fit them before assembly.','organizer',
 'Fabricators use a cut list to avoid wasting stock. You will transfer dimensions and account for the actual wall thickness.',
 'Previous prototype, clean thin packaging card totaling at least 130 in² of usable area per crew, and 12 in of temporary tape. '+TRAY,
 'Use B’s part labels and top/front views. Height is 2 in above the base; depth is 6 in front-to-back. A wall blank’s length is not the same as the finished inside gap.',
 ['Measure usable stock. Lay out 8 × 6 base, two 8 × 2 walls and four 6 × 2 blanks; each student marks at least one part.', 'Mark D1/D2 positions at 2 5/8 and 5 1/4 in from the base’s left edge. Check both endpoints before drawing each line.'],
 ['Make a cut-list table: part | quantity | blank length | height/depth | final fitted length. Enter B×1, F/R×2, E/D×4.', 'Draw the rectangles on available stock with no overlaps. Shared scissors cuts need no added saw kerf. Preserve long straight offcuts.'],
 ['Cut B, F and R first. Label each part on the face that will be outside.', 'Temporarily tape F/R upright on B with outer faces flush to the base edges.', 'Use a narrow scrap strip to capture the inside gap: hold one end against F, mark where it meets the inside face of R, then measure that length.', 'Transfer that gap to all four short-wall blanks. Mark a waste X on the portion to remove.', 'Partner checks the first marked short wall; trim it and test it between F/R without bending either wall.', 'Trim the remaining three to the same checked length. Label E1/E2/D1/D2.', 'Dry-fit all seven pieces in their specified positions. Do not permanently tape partitions today. Bundle small parts in the base with the cut list.'],
 ['Each short wall fits between F/R without force and with no end gap greater than 1/8 in.', 'Check one 8-in part and one fitted part independently. Record intended, actual and signed difference; ±1/8 in is the classroom cutting tolerance.'],
 ['Seven labeled durable parts that dry-fit the tray plan.', 'Notebook: stock layout, complete final cut list and two inspection readings per student.'],
 'Collect seven sets of thin, clean packaging card that scissors can cut. Adult-precut thick corrugated material; do not introduce utility knives to this lesson. Supply two spare short-wall blanks per crew.',
 'Model measuring the actual inside gap with a story strip. Compare the physical gap with the example 6 − 2(1/8) = 5 3/4 in. Explain that their fitted length comes from their own stock.',
 'Inspect one cut per student before the rest are cut. The list must name which parts share the same fitted length; students may not silently use 6 in for all four.',
 'Too short → replace that part using a spare; tape cannot restore a missing wall length accurately. Too long → mark and trim only the excess. Stock too thick for scissors → teacher substitutes thinner card or supplies precut blanks.')

add(1,'Assemble and Reinforce the Supply Tray','Assemble the durable tray and add four folded corner reinforcements; compare it with the folder prototype.','organizer',
 'A stronger joint consumes material and time. You will make that change deliberately and calculate a transparent classroom material cost.',
 'Seven durable parts from day 3, prototype, four 2 × 2-in card squares, the same test supplies, and a measured 48-in tape allowance.',
 'Use B’s assembly labels. The four extra squares become angle brackets: one vertical center fold makes two 1 × 2-in legs; each leg attaches to a different wall at an inside corner.',
 ['Measure and mark the four 2 × 2-in squares and their 1-in center folds.', 'Record starting tape allowance 48 in; measure unused tape at the end. Use the final cut-list dimensions, not the raw blank sizes, for area.'],
 ['Copy revision B onto the top view and mark the four reinforced outside corners.', 'Set up a material table: card area (in²), tape used (in), tape used ÷ 12 (ft). The worked example uses supplied classroom prices, not actual store prices.'],
 ['Tape F/R to B, then fit and tape E1/E2 using the checked part lengths.', 'Put D1/D2 left faces on their marked lines; tape bottoms and ends.', 'Fold each reinforcing square 90 degrees along its centerline.', 'Fit one bracket vertically inside each outer corner. Tape one leg to the long wall and one to the end wall; leave the bottom against B.', 'Move the same supplies from the prototype into the same labeled bays.', 'Run the retrieval test on both versions. If a reinforced corner catches an object, trim only the projecting tape and retest.', 'Measure remaining tape and calculate used length. Label the durable tray revision B and retain prototype A.'],
 ['For each version, remove/return each supply type three times. Count snags and loose joints using the same operator and objects.', 'Measure outside width and one clear bay. Check that reinforcement did not block the assigned objects.'],
 ['An assembled durable three-bay tray with four angle brackets; prototype retained.', 'Notebook: before/after retrieval table, finished dimensions and actual tape-use calculation.'],
 'Have seven 48-in tape strips on backing sheets plus replacement stock for failed joints. State that the tape allowance is a measurement budget, not a reason to leave a needed repair unsafe or incomplete.',
 'Show a flat square becoming an inside-corner bracket. Demonstrate that the two legs join two different walls. Calculate one sample area and convert 24 in of tape to 2 ft.',
 'Look for real corner brackets, unchanged test objects, and a measured tape remainder. Both students must name a changed joint and explain the purpose.',
 'Bracket blocks a bay → flatten it tightly against the corner; remove protruding tape. Tray still flexes → check the wall-to-base seam before adding decorative layers. Cost differs from example → use their measured quantity and the explicitly supplied price.')

add(1,'Inspect and Hand Over the Finished Tray','Deliver the three-bay tray, a matching top/front drawing and a completed fit inspection.','organizer',
 'A customer needs a working product and a drawing that matches it. An inspector must separate dimensional tolerance from functional fit.',
 'Both tray versions, original test supplies, final cut list and one blank inspection page.',
 'Read B’s top view for width/depth/partition locations; read its front view for wall height. Update your own drawing to match the actual revision.',
 ['Individually measure outside width, depth and one clear bay. Record intended | actual | difference | pass/rework.', 'Use outside width 8 in ±1/8 and depth 6 in ±1/8 as classroom checks. Clear-bay fit is checked with its assigned object.'],
 ['Draw the final top and front views with units, datum, actual partition positions and revision B.', 'Write this three-line handover: what goes in each bay; how to move the tray (support the base); which joint was improved.'],
 ['Exchange tray and drawings with another crew. Inspect without changing their work.', 'Identify one mismatch between drawing and object; if none is found, record “no mismatch found” and the dimensions checked.', 'Return the tray. Its owners correct the marked drawing or refit the inaccurate part, then repeat the affected measurement.', 'Run the nine retrieval attempts with the original supplies.', 'Give the receiving crew a 60-second handover using the object and drawing.', 'Each student shows the teacher one tape reading and traces one part from plan to object. Store both versions in the labeled tray.'],
 ['All three supply types fit and can be retrieved without lifting the tray; note each failure.', 'Drawing and product agree within the stated checks. A dimensional pass does not excuse a failed retrieval.'],
 ['A handed-over working tray, two-view drawing and honest inspection record.', 'Each student completes the app transfer answer and a live tape/plan check.'],
 'Pair crews for exchange and prepare a roster with three separate columns: math, measuring, plan reading. Spend the make interval circulating for short individual checks.',
 'Model a signed error: 8 1/8 − 8 = +1/8 in. Show where the top and front views describe the same wall. Model one concise handover.',
 'Record independent / with cue / not observed separately. Require the student to place the tape and read it; do not accept the partner’s number as an individual check.',
 'Drawing differs from a sound product → revise the drawing and label the revision. A required item still snags → fix the contact point, then repeat all three attempts for that item.')

add(1,'Clinic: Make a Four-Center Mounting Template','Individually make a paper mounting template with four located centers; use the skill to inspect the tray.','template',
 'Installers locate holes from edges and centers. The paper template lets you practice that skill without drilling.',
 'One 8 1/2 × 5 1/4-in paper rectangle per student, one spare sheet and the completed tray.',
 'C gives four center marks 3/4 in from their two nearest edges. Mark centers only; do not cut holes.',
 ['Choose lower-left as (0,0). Mark x = 3/4 and 7 3/4 in along bottom and top.', 'Mark y = 3/4 and 4 1/2 in along left and right. Draw light crossing guide lines.'],
 ['Copy a center table: left-bottom (3/4,3/4), right-bottom (7 3/4,3/4), left-top (3/4,4 1/2), right-top (7 3/4,4 1/2), all in inches.', 'Calculate the horizontal and vertical center spacing before marking the centers.'],
 ['Lay out the rectangle independently. Cut its outside edge only.', 'Use the four guide-line intersections to draw four small crosses.', 'Exchange templates; checker measures offsets from the named datum without correcting marks.', 'Mark an inaccurate cross with a small circle, then make the corrected cross beside it. Keep the first attempt visible.', 'Draw revision B with horizontal offsets of 1 in from each side; keep vertical offsets 3/4 in.', 'Return to the tray and independently check one partition’s position from its left outside edge. Correct its drawing if needed.'],
 ['All four original centers are within ±1/16 in of their specified positions.', 'Revision B horizontal spacing is checked separately; retain both versions.'],
 ['Two individually marked paper templates and one tray position check.', 'Notebook includes coordinates, spacing calculation and any correction.'],
 'This is the defined flex lesson when extra practice is needed. Print C and provide larger fraction strips for students who need them; all still make their own final template.',
 'Demonstrate one center with two edge offsets. Show that a center is the intersection of two locations, not the corner of a drawn box.',
 'Ask students to read 7 3/4 on the tape and distinguish overall width from center spacing. Each student keeps their own sheet.',
 'Offsets measured from different unmarked ends → relabel datum and remeasure. Crosses correct but spacing wrong → measure center-to-center, not from a paper edge.')

add(2,'Build and Load-Test Two Paper Towers','Build two 11-in paper columns supporting a 6 × 6-in platform; add base ties and repeat the same capped load test.','tower',
 'Builders need a continuous load path and stable supports. A capped test shows what the model carried under specified conditions.',
 'Two letter sheets for two 6 1/2 × 11-in column blanks, two 6 × 1-in offcut ties, one 6 × 6-in card platform, one small paper cup, ten identical large paper clips and 36 in of tape.',
 'D shows two triangular columns. Each blank folds at 2, 4 and 6 in across its 6 1/2-in width; its full 11-in length is the height. The final 1/2 in is an overlap.',
 ['Mark both blanks from the same long edge at 2/4/6 in; measure height 11 in.', 'Draw a 6 × 6-in footprint on scrap. Keep both columns and platform inside it.'],
 ['Sketch the side and top views; show the two triangular column footprints under the left/right sides of the platform.', 'Prepare a load table with rows 0 through 10 clips for version A and B. The cup/platform are the same in both tests.'],
 ['Cut, fold and tape each blank into a triangular tube with three 2-in faces. Keep both ends level.', 'Stand the columns on the marked footprint, one under each side of the platform. Place the 6 × 6-in platform across them; tape its contacts lightly.', 'Put the empty cup at the platform center. If it cannot support the cup, repair the column seams before recording a load trial.', 'Add one paper clip every five seconds up to ten. Stop immediately if a column tips, folds or the platform falls; do not catch a falling load with the model.', 'Unload. Cut two 6 × 1-in ties from offcuts. Tape one tie across the front column bases and one across the rear bases to resist spreading; do not tape the tower to the table.', 'Repeat the same 0–10-clip test with the same cup, platform and placement. Record the cap if both versions hold ten.'],
 ['Freestanding footprint no larger than 6 × 6 in; height 11 in ±1/4.', 'Record last load held for five seconds and failure location. Ten clips means “held the test cap,” not “maximum strength is ten.”'],
 ['One tower with two triangular columns and removable base ties.', 'Two load records and an annotated load-path sketch.'],
 'Prebuild one sample using the actual paper. Use large paper clips as identical low-mass loads; count rather than infer newtons. Test at tabletop height with the area clear of faces.',
 'Show the 1/2-in column overlap and level ends. Trace load from cup to platform, columns and tabletop. Explain when to stop and how to record a capped result.',
 'All crews use two equal blanks and identical loading increments. Check ties connect column bases, not the tabletop.',
 'Top tilts before loading → unequal column ends; square the ends or remake. Both reach cap → report the tie; the next lesson tests shape under a different loading condition.')

add(2,'Compare Flat, V and Channel Beams','Make three equal-paper beams and compare midpoint deflection over the same 8-in gap.','beam',
 'Cross-section changes stiffness without necessarily changing material quantity. You will measure that effect before choosing structural shapes.',
 'Three 10 × 3-in paper strips, two equal-height book stacks, one small paper cup with five large paper clips, and a vertical ruler.',
 'D2 labels an 8-in CLEAR span with 1 in bearing at each end. Sample A is flat; B has one lengthwise center fold (V); C has lengthwise folds 1 in from each edge (channel).',
 ['Set inside faces of the book stacks exactly 8 in apart. Mark the strip ends at 1 and 9 in.', 'Measure the midpoint height relative to the tabletop, first empty and then loaded; use the same point on the beam.'],
 ['Sketch the three end-on cross-sections and label equal blank area 10 × 3 = 30 in².', 'Make table: shape | unloaded height mm | loaded height mm | deflection mm | collapsed?'],
 ['Leave A flat. Fold B lengthwise at 1 1/2 in to make an open V. Fold C at 1 and 2 in to make a U-channel with a 1-in floor and upright sides.', 'Place A with 1 in resting on each support. Mark its midpoint at 5 in from an end.', 'Measure unloaded midpoint height. Place the same cup with five clips at the midpoint, release and measure after five seconds.', 'Remove the load and repeat with B, ridge down so the cup bridges its upper edges, then C, channel opening up.', 'Repeat the three tests once. If a beam collapses, record collapse instead of inventing a deflection.', 'Make a second copy of the least-deflecting shape. Recheck its span and loading to see whether the result repeats.'],
 ['All blanks have equal area and use the same span, bearing, cup and clip load.', 'Report two trials per shape. Do not call a collapsed specimen “zero deflection.”'],
 ['Three labeled beam shapes and one repeated sample.', 'Notebook cross-sections and six test rows.'],
 'Use identical book heights and the same cup/load at all stations. Precheck that midpoint can be observed beside the cup. Have spare paper for collapsed specimens.',
 'Show clear span versus total length using the support faces. Demonstrate loaded and unloaded readings from one fixed tabletop reference.',
 'Measure one student’s 8-in gap and observe how they subtract heights. A bending result is not proof of compression-column strength.',
 'Cup rolls or tips → center it and use the same broad-base paper cup for every shape. Beam slides → align bearing marks; do not silently add tape supports to only one sample.')

add(2,'Survey a Doorway and Lay Out the Community Room','Measure a real doorway, then make the supplied community-room floor plan. Keep the two sets of dimensions separate.','building',
 'Surveyors record existing conditions; designers read proposed conditions. Mixing them can put an opening in the wrong place.',
 'Two sheets of paper and access to one teacher-designated classroom wall/doorway; two 1 × 2-in card table tokens and one 1/2 × 1/2-in person token.',
 'E is the required fictional community room: 16 × 12 ft; south door begins 2 ft from southwest corner and is 3 ft wide. Survey measurements do not replace E’s dimensions.',
 ['At the designated doorway, identify the classroom-side left wall corner as survey datum. Measure corner-to-near-jamb and opening width to nearest 1/4 in.', 'Measure twice, with roles swapped. Record both readings in feet/inches AND total inches. Keep the passage clear.'],
 ['Title one sketch EXISTING DOOR SURVEY and show the datum and two actual measurements.', 'On a second sheet draw the PROPOSED ROOM at 1/2 in = 1 ft: 8 × 6 in, north at top, door opening along bottom from x=1 to 2 1/2 in.'],
 ['Mark the model floor rectangle and door jambs from the southwest datum.', 'Cut two 1 × 2-in table tokens and label them 2 × 4-ft tables.', 'Put both tables against the north edge, with their 2-in sides east-west. Leave 1 in between them.', 'Cut a 1/2-in square person token. Move it from the south entrance to each table without crossing a table.', 'Trace a clear route on the floor plan. If blocked, move only the eastern table toward the east wall and repeat.', 'Attach tokens with small tape loops so they remain movable. Store the floor plan for the next lesson.'],
 ['A partner locates the surveyed opening from written dimensions alone.', 'The proposed plan remains exactly 8 × 6 in with the specified door position. The token can reach both tables; this is a model-use test, not an accessibility certification.'],
 ['One measured survey sketch and one proposed floor layout with two table tokens and a clear route.', 'Notebook labels distinguish measured school values from supplied design values.'],
 'Name the actual survey door before class. Put a small removable datum label at the agreed classroom corner. Assign crews staggered survey turns while others begin the proposed layout.',
 'Measure one door width and convert feet/inches to total inches. Then point to E and say: “This separate design stays 16 by 12 feet, regardless of our survey.”',
 'Check students have two clearly titled drawings and record repeat readings, not an unexplained averaged guess.',
 'Feet written as decimal inches → model 9 ft 8 in = 116 in. Proposed doorway copied from real room → restore the supplied design and retain survey on its separate page.')

add(2,'Build the Scale Room and Working Door','Make the 8 × 6-in community-room shell with 4-in walls, a hinged south door and movable table tokens.','building',
 'A coordinated plan and elevation must describe the same opening. You will transfer real dimensions to a physical model.',
 'Thin folder/card stock for the five room parts, previous floor layout/tokens, 48 in tape. '+ROOM+'Roof is made on day 6.',
 'E shows floor plan and south elevation. A 3 × 7-ft door becomes 1 1/2 × 3 1/2 in. West jamb is 1 in from the model southwest corner in both views.',
 ['Mark base 8 × 6 in and N/S walls 8 × 4 in. Mark E/W blanks 6 × 4 in.', 'On S mark door jambs at x=1 and 2 1/2 in, and lintel 3 1/2 in above the bottom edge.'],
 ['Draw south elevation 8 × 4 in with the same door dimensions. Label all model dimensions in inches and write the full-size scale.', 'Copy the five-part cut list and label outside faces N/S/E/W.'],
 ['Cut base and four walls. On S cut the right jamb and top of the door; fold along the left jamb to leave a hinged door flap. The bottom edge is already free.', 'Tape N and S upright on top of the base with outer faces flush to the base edges; keep the door free of tape.', 'Dry-fit E/W BETWEEN N/S. Mark the actual inside gap and trim their width so the shell closes without bowing.', 'Tape E/W to base and adjoining walls. Use small inside and outside tape pieces at each joint.', 'Label north and datum SW on the base. Return the two table tokens to their recorded positions.', 'Swing the door inward at least 90 degrees. Move the person token from entrance to each table.', 'Adjust only table positions if they block the door/route; update their positions on the plan.'],
 ['Base is 8 × 6 in and wall height 4 in, each within ±1/8 in. Door opening dimensions and offset are within ±1/16 in.', 'Door opens 90 degrees without touching furniture; top and front drawings agree with actual door location.'],
 ['A four-wall room model with working hinged south door and two tables; no roof yet.', 'Coordinated top/front drawings and at least four model scale conversions.'],
 'Precut thick card if required; thin folder stock permits student scissors. Show one completed shell and the door’s two cut edges/one fold edge.',
 'Demonstrate the conversion and point to the same left jamb in plan, elevation and physical wall. Cut only top and right of the door; a loose rectangle is not the intended hinge.',
 'Check two conversions independently before cutting. At assembly inspect E/W dry-fit and datum consistency.',
 'Door cut off → reattach left edge with a tape hinge and record repair. Wrong corner used → relabel outside face before trimming. Door rubs base → trim a very small bottom sliver and record the clearance.')

add(2,'Test a Wall Frame and Add a Diagonal','Build a separate 6 × 8-in joint-center frame, test its racking and add a diagonal brace; then reinforce the model room’s corners.','frame',
 'A diagonal changes how a rectangular frame resists shape change. You will connect a measured test with a bracing decision.',
 'Two 9 × 1-in and two 7 × 1-in card strips, one 11 × 1-in brace, four 2 × 2-in corner squares, string, cup with ten large paper clips, two books and the model room.',
 'E2 dimensions run BETWEEN joint centers: 8 in horizontal and 6 in vertical. Each strip extends 1/2 in past each joint center; diagonal center spacing is 10 in.',
 ['Mark each strip centerline and points 1/2 in from its ends. Mark brace attachment centers 1/2 and 10 1/2 in from one end.', 'Measure both frame diagonals between joint centers before the test; a square 6 × 8-in rectangle has two 10-in diagonals.'],
 ['Sketch the four joint centers as a 6 × 8-in rectangle. Draw the brace from bottom-left to top-right.', 'Make table: unbraced / braced | starting top-right height | loaded height | downward movement, in mm.'],
 ['Arrange the two long strips horizontally and short strips vertically with center marks overlapping. Tape each overlap on both faces; keep joints flexible enough to rack.', 'Stand the frame vertical. Sandwich its left upright between two upright books and tape it to the outer book face so both left joint centers stay fixed. Teacher checks the books are stable.', 'Tie the loaded cup to the TOP-RIGHT joint with a short string. Keep the cup close to the tabletop; no one holds the right side.', 'Measure the top-right joint height from the tabletop before loading and after five seconds of load. Remove the cup.', 'Return the frame to its original rectangular shape. Tape the diagonal between bottom-left and top-right centers; use the 11-in strip’s 1/2-in end allowances.', 'Repeat with the identical cup/clip load and fixed left side.', 'Fold each 2 × 2-in square into an angle bracket. Tape one inside each corner of the model room without blocking its door; label this model revision B.'],
 ['Compare vertical movement at the same joint under the same load. Report any movement too small to resolve with the ruler.', 'Check the brace joins opposite joint centers and the room door still swings 90 degrees.'],
 ['A braced test frame and four reinforced corners on the room model.', 'Two diagonals and before/after racking data with a labeled frame sketch.'],
 'Set up and rehearse the book fixture with the actual card. Use ten paper clips in the same cup for both tests, not an unspecified hand push. Stabilize book bases with another flat book if needed.',
 'Show the difference between a 9-in strip and its 8-in joint spacing. Hang the cup from the same top-right point twice; demonstrate how the ruler reads vertical movement.',
 'Check the 6/8/10 triangle arithmetic and observe that the left side remains fixed. A small or tied result is acceptable; it is not full-size structural validation.',
 'Whole fixture moves → stabilize books and repeat; that trial is invalid. Brace loose → tape at the center marks. Frame collapses → unload and repair; record failure instead of a fictitious displacement.')

add(2,'Close the Room and Count the Material','Make a removable roof and a materials takeoff for the model’s walls, door opening and roof.','building',
 'Estimators subtract openings and distinguish surface area from purchased sheet quantities. A removable roof lets the next worker inspect the interior.',
 'Model room, one 8 × 6-in card roof, two 2 × 1-in card locator strips and 12 in tape.',
 'E supplies nominal outside dimensions. Roof is 8 × 6 in. The south wall’s door area is 1 1/2 × 3 1/2 in; keep the hinged door even though the opening is excluded from wall-covering area.',
 ['Measure the actual outside roof-bearing rectangle and compare with 8 × 6 in.', 'Measure door opening, not the flap including any overlap. Record the model’s actual dimensions separately from nominal takeoff values.'],
 ['Calculate nominal wall area: two 8 × 4 plus two 6 × 4; subtract door area once. Add 8 × 6 roof separately.', 'Draw the roof underside with two locator tabs near the north/south edges. These keep the roof from sliding; it stays lift-off.'],
 ['Cut roof 8 × 6 in. Mark underside and north edge.', 'Fold each 2 × 1-in strip at its midpoint to make an L with 1-in legs.', 'Place roof upside down. Tape one leg of a tab near the center of its north edge; locate the fold just inside the actual north wall position.', 'Fit the roof. The free tab leg drops INSIDE the north wall. Mark and attach the second tab to fit inside the south wall.', 'Lift and replace the roof three times. Trim tab width or adjust its location if it catches a wall.', 'Write a small material label under the roof: nominal wall covering, roof area and actual card used.'],
 ['Roof covers the wall tops and lifts off without pulling walls apart; repeat three times.', 'Takeoff subtracts the door once: wall covering 106 3/4 in²; roof 48 in². Treat overlaps and actual stock cutting waste separately.'],
 ['One room model with removable located roof.', 'Notebook takeoff with units, door subtraction and a sketch of the tab detail.'],
 'Prepare spare roof stock and a sample locator tab. The given model-area key is for nominal panels; actual end-wall trimming changes precise consumed area.',
 'Demonstrate net area by shading the door opening. Show a roof tab under the lid instead of taping the roof permanently shut.',
 'Check students distinguish in from in² and roof from wall area. Ask each to point to the opening being subtracted.',
 'Roof pulls wall inward → tabs too far inside; reposition. Door area counted twice → one opening in one wall. A sheet-area total alone does not prove the cut layout will fit.')

add(2,'Build and Test an Insulated Cup Enclosure','Make a two-layer paper enclosure for one ice cup and compare it with an identical uninsulated control cup.','thermal',
 'Envelope performance requires a fair comparison. You will keep starting ice, time and handling the same while changing the insulation.',
 'Two identical dry 240–250-mL plastic cups, two identical paper/card lids, two letter-paper sheets, tape, tray, timer, sieve, catch cup, 1-g balance and 120 g ice per crew (60 g for each cup). Shared balance station is acceptable.',
 'F shows the same inner cup in control and insulated conditions. Both have identical flat lids; only the test cup gets the paper wrap and bottom pad.',
 ['Measure cup circumference with a paper strip, marking one full wrap; measure cup height with ruler.', 'At the balance station tare each dry cup and add 60 g ice to each. Start both cups together.'],
 ['Draw a section: cup, two paper wrap layers and 1/2-in crumpled-paper bottom pad. Label the control’s matching lid.', 'Prepare table: cup | starting ice g | elapsed min | collected melt g | observations. Test interval is 20 min.'],
 ['Cut two paper strips each cup-height tall and circumference + 1 in long. Tape them end-to-end if needed to reach that measured length.', 'Wrap the test cup twice, one strip at a time, loosely enough to leave small air spaces; tape only the seams. Keep paper dry and outside the cup.', 'Make a 1/2-in-thick lightly crumpled pad from remaining paper and place it under the test cup. Control sits directly on the same tray.', 'Add the equal ice masses, put matching lids on both and start a 20-minute timer. Keep them side-by-side away from sun/vents.', 'During the wait, make a 4 × 4-in two-layer wall sample for the model room and draw its layers; do not disturb cups.', 'At 20 minutes drain each cup through the same sieve into the tared catch cup for 30 seconds. Weigh the collected melt, drying/taring the catch cup between samples.', 'Calculate control melt minus insulated melt. Calculate percent reduction only if control melt is greater than zero; keep all readings even if insulation did worse.'],
 ['Both start with 60 g ice, have the same lid and run for the same 20 minutes; record any deviation.', 'Readings at/below the 1-g instrument resolution are inconclusive. Do not replace them with the worked example or claim an R-value.'],
 ['One insulated cup enclosure and one 4 × 4-in wall-layer sample.', 'Actual control/test melt results, a section sketch and a supported comparison.'],
 'Collect matching cups, ice, a sieve and 1-g balance before release. Run one 20-minute preparation check to ensure melt is measurable in the room. If not, schedule a longer whole-class interval and print that single interval before class; do not improvise different times per crew.',
 'Demonstrate tare, equal starting mass and the 30-second drain. Explain that we weigh melt, not water plus cup, and that both cups receive identical lids.',
 'Launch thermal tests early in Make so the 20-minute wait fits. Use the waiting interval for the wall sample. Check both times and all mass units.',
 'Wet paper → note changed conditions and remake for a repeat. No measurable melt → report insufficient resolution; continue wall sample and arrange a longer repeat. Zero control melt → percentage is undefined.')

add(2,'Seal One Insulation Gap and Retest','Improve the insulated cup’s top-edge fit, repeat the comparison, and add a removable insulation panel to the room.','thermal',
 'A redesign needs one identified change and comparable test conditions. You will change the top-edge seal while holding the rest of the test constant.',
 'Previous cup enclosure and wall sample, fresh equal ice masses, identical control materials, same balance/test equipment, one 4 × 1-in paper strip and two tape loops.',
 'F’s layer section now receives a paper collar around the test cup top. The matching control keeps the same original lid. This is a revision to the cup enclosure, not proof of whole-building performance.',
 ['Measure the largest gap between insulation wrap and lid; record to the ruler’s nearest division.', 'Measure the north wall panel area to confirm the 4 × 4-in sample will fit without covering a door or roof locator.'],
 ['Draw revision C with the added collar. Keep the original section visible; circle only the new piece.', 'Copy original melt values and conditions into a before/after table. Each new run also needs its own control cup.'],
 ['Dry the enclosure completely. Replace damaged paper with the same number of layers.', 'Make a 1-in-high collar of paper, length = measured cup circumference + 1 in; join strips if required. Fit it around the top of the wrap to bridge the lid-edge gap; do not add layers elsewhere.', 'Repeat the equal-ice, matching-control test for the same agreed interval and 30-second drainage used on day 7.', 'During the wait, attach the 4 × 4-in wall sample inside the north wall using two removable tape loops.', 'Lift the roof, remove/replace the panel and swing the door 90 degrees. Adjust loops if access is blocked.', 'Compare each insulated result with its own control. If melt is greater after revision, keep the data and write that the change did not improve this trial.'],
 ['One intentional thermal change: top collar. Same mass, interval, lids, location and procedure.', 'Model panel is removable; door and roof access still work.'],
 ['Revised cup enclosure and model with removable wall-layer panel.', 'Before/after sections and two control-referenced melt comparisons.'],
 'Use the same equipment and interval as day 7; dry the materials before retest. Retain original data. Do not replace the experiment with a generic “improve something” task.',
 'Show the specific top-edge gap and one collar solution. Model comparing control/test pairs before making an improvement claim.',
 'Check the changed feature exists and only one thermal feature changed. Ask each student to locate the collar in the section drawing.',
 'Multiple changes made → label them; do not claim the collar alone caused the result. Roof catches insulation → move the removable panel lower and retest access.')

add(2,'Inspect the Community-Room Model','Hand over the room model with a working door, removable roof/panel and matching drawings.','building',
 'Construction inspection checks a list of specified features. A model can look finished while its views or opening dimensions disagree.',
 'Completed room, top/south elevation/layer-detail drawings, person/table tokens and test records.',
 'Use E for nominal room dimensions, F for the insulation detail and your revision labels for changes. Inspect the same feature across views.',
 ['Each student measures the 8-in width, 6-in depth, 4-in height and door’s 1-in west offset.', 'Convert one actual model dimension back to feet using ÷ 1/2 in per ft; label it a represented dimension.'],
 ['Set up inspection table: feature | required | measured | difference | action.', 'Required checks: shell ±1/8 in; door width/height/offset ±1/16 in; door swing 90 degrees; roof/panel removable.'],
 ['Exchange model and drawing set with another crew.', 'Inspect dimensions without changing their model. Move the person token from entrance to both tables.', 'Remove and replace roof and insulation panel three times each; record catches or damage.', 'Return inspection sheet. Owners repair one reported mismatch, or independently recheck a dimension if no fault was found.', 'Update drawings to match the repair. Give a one-minute demonstration of door, route and removable pieces.', 'Show your teacher one independent measurement and one scale conversion. Store model and test-frame together.'],
 ['Every specified dimension has a recorded value; functional tests have explicit pass/fail.', 'Thermal claim cites actual cup data and does not claim a code rating or full-size building safety.'],
 ['Inspected room model and coordinated three-view/detail set.', 'Each student has an individual scale, tape and plan-reading check.'],
 'Prepare seven inspection sheets with the listed dimensions and pair crews. Use the same tolerances introduced during fabrication.',
 'Model an inspection entry including a failing value and an action. Show how a good drawing can document an unsuccessful experiment honestly.',
 'Student locates datum and door independently. A group demonstration does not replace the individual measurement.',
 'Drawing disagrees → identify which represents the intended requirement, then correct the other. Roof sticks → inspect tab locations before forcing it.')

add(2,'Clinic: Move the Door and Coordinate Both Views','Make a replacement south wall with the door shifted to a 3-ft west offset, then update both drawings.','building',
 'A change order must reach every affected drawing and part. Today’s required change is precise: west offset becomes 3 ft; door size stays 3 × 7 ft.',
 'Room model, fresh 8 × 4-in south wall, 18 in tape and spare drawing paper.',
 'Original E has a 2-ft offset. Change order C-01: use 3 ft, which becomes 1 1/2 in in the model. New door edges are x=1 1/2 and 3 in.',
 ['Measure and record the old door offset before removal.', 'Mark the new jambs and 3 1/2-in height from the same west/bottom datums on the replacement wall.'],
 ['Cross out the old 2-ft offset with one line on plan and south elevation; write 3 ft, C-01 and date.', 'Calculate model movement and mark both old and new jamb locations on a comparison sketch.'],
 ['Cut top and right jamb of the new door; fold left jamb as before.', 'Remove the old south wall by peeling its tape; retain it as revision B.', 'Fit the new south wall with outer face flush to base. Tape to base and end walls while leaving the door free.', 'Move a table token only if the new door arc interferes; update that location on the plan.', 'Check new door offset, size, swing and token route.', 'Exchange views with a partner and have them locate the new opening without verbal help.'],
 ['New left jamb is 1 1/2 in from west datum within ±1/16; opening size is unchanged.', 'Plan, elevation and physical wall all show C-01.'],
 ['A physically relocated door and two coordinated revised views.', 'Notebook change record and original wall retained.'],
 'This flex meeting uses the stated change order; no design decision is left for the teacher to invent. Have a removable sample wall joint ready.',
 'Demonstrate the 1/2-in model shift and update both views before touching the model.',
 'Check students move both jambs and preserve opening width. Require one independent conversion.',
 'Only one jamb moved → opening width changed; remake the flap. Offset measured from door flap rather than west wall end → reset the datum.')

add(3,'Compare Air and Water Syringe Motion','Operate air and water syringe pairs; attach a paper indicator and measure actual input/output travel.','fluid',
 'Hydraulic technicians distinguish fluid behavior from mechanical binding. We will use measured motion, not how “strong” a system feels.',
 'One matching 20-mL syringe pair, 60-cm tube, water tray and towel, two 1/4 × 2-in paper pointer strips and removable tape. Teacher prepares the water fill after the air trial.',
 'G labels INPUT (hand-operated) and OUTPUT (remote). Barrel stays fixed; the plunger moves. Stroke is change in plunger position, not barrel length or mL capacity.',
 ['Set input to 15 mL and output to 5 mL before connecting the air-filled tube.', 'Tape a paper pointer to each thumb pad. Lay a ruler beside each barrel, parallel to its axis, and mark the pointer starting position.'],
 ['Draw input → tube → output. Label air trial pneumatic and water trial hydraulic.', 'Make six rows: fluid | trial | input travel mm | output travel mm | bubbles/response. Target hand stroke is 20 mm.'],
 ['Place both syringes flat in the dry tray; partners hold BARRELS, not output plungers.', 'Move input forward slowly by 20 mm while partner reads output travel. Stop if resistance rises sharply; never force.', 'Pull input back to its original mark. Repeat three trials, swapping operator and reader.', 'Take the pair to the teacher for water filling at the same 15/5-mL starting positions. The tube and both tips must be water-filled, with visible bubbles removed.', 'Wipe outside dry. Repeat the same three 20-mm strokes and resets with water.', 'Check tip joints for drops and circle any delayed or unequal motion. Save the water-filled pair capped within its tray.'],
 ['Input/output travel comes from pointer start/end positions in mm. Both students take an actual reading.', 'Equal-bore ideal liquid prediction is equal travel; record actual results even when they differ.'],
 ['A working water-filled pair, clearly labeled input/output.', 'Six measured trial rows and a connection sketch.'],
 'Prepare seven compatible pairs. Use a spare water-filled syringe to flush each tube before joining under the tray waterline. Never fit needles. Confirm each plunger has at least 20 mm safe motion from its start.',
 'Demonstrate holding a barrel while watching the moving thumb pad. Contrast milliliters on the barrel with millimeters of travel. Show the gentle stop rule.',
 'Check that a student does not assist the output plunger. Air and water comparisons use matching syringes and the same stroke.',
 'No output → check loose tube/leak and plunger sticking before retrying. Springy water trial → inspect trapped air; teacher refills. Hard stop → stop hand force and reset; do not squeeze harder.')

add(3,'Build the Syringe-Powered Delivery Sled','Mount the output syringe on a card base and attach a sliding card sled that moves out and back with the hand input.','sled',
 'An actuator must be mounted so the moving part can do useful work. This device delivers a light paper load to a marked position without touching the sled.',
 'Prepared water pair, card stock for the base, two saddle strips, one sled blank, 30 in tape and one 1 × 1-in paper cargo square. '+SLED,
 'G2 is the required assembly. The syringe lies horizontally, nozzle pointing LEFT. Its plunger points RIGHT. The sled’s upright 1-in tab attaches to the output thumb pad; the 2 × 2-in deck extends to the right.',
 ['Mark base datum A at lower-left; draw centerline y=3 in. Mark nozzle location x=3 in.', 'With output at 5 mL, check there is room to its right for the 2-in sled deck plus at least 20 mm travel before the base edge. Teacher checks fit before taping.'],
 ['Label base, fixed barrel, two saddle straps, moving plunger, sled tab/deck and tube on the assembly sketch.', 'Record two saddle locations on the smooth barrel, clear of nozzle, printed start reading and moving plunger/flange. These locations depend on the actual syringe body; measure and record them.'],
 ['Cut base to 12 × 6 in. Cut two 4 × 1-in saddle strips and sled blank 3 × 2 in.', 'Fold sled across its 2-in width at 1 in from a short end. Stand the 1-in tab upright; the remaining 2 × 2-in deck lies on the base.', 'Lay output on centerline, nozzle at x=3 in and pointing left. Keep its 5-mL start position.', 'Curve each saddle over the fixed barrel, then crease its two ends down onto the base. Tape those ends firmly to the base. Do not tape or pinch the moving plunger.', 'Put the sled tab against the right-facing flat thumb pad, deck extending right. Tape tab to pad on both accessible sides; the deck must slide flat rather than hang above the base.', 'Route the 60-cm tube in a broad loop to input off the left side. Tape the tube loosely to the base near the nozzle for strain relief; never flatten the tube.', 'Move input slowly 20 mm. Sled should travel right. Pull input back to return the sled; do not reset it by hand.', 'Draw START at the sled’s front/right edge in the reset position and a delivery line 20 mm to its right. Put the paper cargo square on the deck.'],
 ['Do three out-and-back cycles. The input hand is the only drive; output barrel stays fixed and sled clears the base edge.', 'Record actual sled travel each time. Classroom acceptance for equal-syringe travel is 20 mm ±2 mm, after any bubble/mount repair; failures remain recorded.'],
 ['One water-powered sliding delivery sled with start/delivery marks and paper cargo.', 'Dimensioned assembly sketch and three travel readings.'],
 'Preassemble a sample with the actual syringes. With nozzle at x=3 in and output at 5 mL, verify thumb pad plus 2-in deck and 20-mm travel fit a 12-in base. If the selected syringe is longer, supply a longer base and a corrected printed base dimension before release; retain all other dimensions.',
 'Show the finished moving sled, then the fixed and moving parts separately. Demonstrate saddle ends taped to the base and the upright tab attached to the thumb pad. Move only input to prove the mechanical connection.',
 'Inspect each mount before water operation. Both students must locate a base coordinate and measure a stroke.',
 'Sled tilts → refold tab 90 degrees and lower attachment so deck rests on base. Barrel creeps → tighten saddle end tape. Output jams → free plunger from saddle/tape; never force it. Bubbles → teacher reprimes.')

add(3,'Measure Flow Through Two Tube Routes','At the prepared gravity station, time 15 mL of water through straight and curved routes; then secure a smooth tube route on the sled.','flow',
 'Pipe work requires quantities and rates as well as a route drawing. A fair comparison controls starting head, tube and outlet height.',
 'Existing sled. Shared station: 20-mL syringe barrel with plunger removed, stand/clamp, the same 60-cm tube for both routes, catch cup, water tray, ruler and stopwatch.',
 'H specifies vertical reservoir, start at 20 mL and stop at 5 mL: 15 mL passes the marks. Outlet is fixed 10 cm BELOW the 5-mL line. Compare one broad U with a broad S; no sharp kink.',
 ['Measure the reservoir 5-mL-line-to-outlet vertical drop as 10 cm and secure outlet at that height.', 'Measure the same tube’s actual length 60 cm. Record bore only if the kit states it; do not guess from outside diameter.'],
 ['Sketch route A as one broad U and B as a broad S, with identical inlet/outlet locations and no uphill crest trapping air.', 'Make table: route | trial | volume 15 mL | time s | rate mL/s. Three trials for each route.'],
 ['Teacher clamps the upright barrel and secures tube outlet over a cup in the tray.', 'Fill tube completely with water first. Pinch the tube gently near its outlet while filling reservoir above the 20-mL mark.', 'Release. Start the timer as the level crosses 20 mL; stop at 5 mL. Do not touch the reservoir during flow.', 'Refill and repeat twice. Rotate reader/timer/recorder; pairs share the recording role.', 'Rearrange only the middle of the tube into route B, maintaining length and both endpoint heights. Repeat three trials.', 'Calculate 15 ÷ time for each valid trial. A tied result is acceptable; hand timing limits small comparisons.', 'Reconnect the teacher-checked water pair on the sled. Route its tube in a broad untwisted loop and tape a loose guide to keep it away from the moving sled.'],
 ['Three valid timed trials per route; same marks, tube and outlet height. Mark spills or bubbles invalid and repeat.', 'The sled still performs three strokes after reconnection. Gravity-flow results do not directly predict syringe-machine speed under hand pressure.'],
 ['A secured tube route on the sled and two measured route drawings.', 'Six actual rates with conditions and a comparison limit.'],
 'Build and rehearse the gravity station before class. If the 15-mL interval is shorter than reliable stopwatch timing, use slow-motion video timestamps at that station and teach that single timing method. Do not substitute made-up times. Run station groups while other crews inspect sled mounts.',
 'Show the start/stop meniscus crossings and fixed vertical drop. Explain why 15 mL is used even though the barrel says 20 at the start.',
 'Check rates include mL/s and each crew has real station data. Do not claim U versus S must differ.',
 'Flow stops → check air bubble, pinched tube or outlet too high. Level passes before timer ready → refill and repeat. Changed tube length → invalidate comparison and restore 60 cm.')

add(3,'Add a Cargo Fence and Read the Assembly','Attach a three-sided cargo fence to the sled deck and make a complete measured assembly drawing.','sled',
 'Assembly drawings coordinate separate parts. You will locate a load-retaining feature without blocking actuator travel.',
 'Working sled, three 2 × 1-in card strips, one paper cargo square, 18 in tape and a dry tray.',
 'G2 shows the deck 2 × 2 in. Each fence strip folds lengthwise into two 2 × 1/2-in legs. Three fences surround the front/right edge and two side edges; rear actuator tab stays accessible.',
 ['Measure deck width/depth and maximum rightward travel clearance.', 'Mark the centerline 3 in from either long base edge. Measure barrel and saddle coordinates from the same lower-left datum.'],
 ['Draw the base top view and a sled side detail. Include 12 × 6 base, x=3 nozzle, y=3 axis, 2 × 2 deck and 20-mm delivery distance.', 'Add a parts list with two syringes, one 60-cm tube, base, two saddles, one sled and three fence strips.'],
 ['Cut and fold the three fence strips along their centerlines.', 'Tape one flat leg of each strip on the deck, upright leg along each of the two sides and front/right edge. Keep tape off the underside sliding surface.', 'Leave the rear side open at the actuator tab. Do not bridge the moving deck to the stationary base.', 'Place the cargo square inside the fence. Slowly cycle out and back three times.', 'Measure any point where fence or tab touches a saddle. Reposition only the interfering tape/strip; do not change the delivery distance.', 'Exchange drawings; partner identifies all parts on the actual assembly using the labels.'],
 ['Cargo stays on deck for three complete cycles. Fence does not bind or reduce travel.', 'Every listed part can be found on the drawing and object; moving and fixed parts are distinct.'],
 ['A fenced delivery sled with a complete assembly drawing and parts list.', 'Notebook includes centerline/offset measurements and three cargo trials.'],
 'Use the same sled for all remaining fluid lessons. No boat preparation or route choice is required. Provide one fenced sample and spare strips.',
 'Show how folding a 1-in strip creates a 1/2-in fence and attachment leg. Point to the moving/fixed boundary where tape must not cross.',
 'Check actual deck dimensions and travel clearance. Ask each student to identify one symmetric location relative to the base centerline.',
 'Sled stops early → tape likely bridges to base or catches a saddle; disconnect input motion and inspect. Fence hides joint → leave rear open so the thumb-pad connection remains visible.')

add(3,'Find and Repair a Loose Actuator Mount','Diagnose a deliberately loose saddle, repair it, and prove the sled repeats three accurate deliveries.','sled',
 'Repair begins with an observed fault, a predicted cause and a controlled retest. Replacing random parts can hide the original problem.',
 'Working sled, cargo square, ruler, towel and 12 in replacement tape. Teacher prepares one loose saddle end with power supplied only by hand input at rest.',
 'Trace G2 from input through tube to fixed output barrel and moving sled. A moving barrel is a mounting fault; bubbles and leaks are different observations.',
 ['Draw a pencil witness line at the output barrel’s original position on the base.', 'Measure barrel shift and sled travel during one gentle 20-mm input stroke. Stop if the mount releases.'],
 ['Make a fault table: symptom | suspected part | evidence | repair | retest.', 'Circle the suspect saddle on the assembly drawing before touching its tape.'],
 ['Teacher peels one end of the rear saddle from the base; do not disconnect or obstruct the tube.', 'Operate one gentle stroke while partner watches the barrel witness line. Record the symptom.', 'Return input to its start; keep hands off the moving sled. Explain the suspected mount to your partner.', 'Remove loose tape. Reposition barrel on centerline and nozzle datum, then retape the saddle end firmly.', 'Dry the tray and outside connections with a towel. Inspect for fresh drops during three slow cycles; do not treat old tray water as new leakage.', 'Run three cargo deliveries from the same start mark and measure actual travel each time.', 'Add the repair and three results to the fault table.'],
 ['Barrel stays on its witness line and each travel is 20 mm ±2 mm. Record any remaining failure.', 'A repair is complete only after the same motion test repeats without hands holding the output.'],
 ['A repaired, stable sled with accessible connections.', 'Notebook contains symptom, evidence, a named repair and retest readings.'],
 'Use only the specified loose-saddle fault. Do not make leaks or pressure blockages as surprise faults. Return input/output to their marked reset positions.',
 'Show that input motion may move an unsecured whole syringe instead of delivering useful plunger motion. Model observing first, repairing second.',
 'Have students name the witness-line evidence. Independently ask one to measure output travel and one to locate the saddle on the drawing; swap next check.',
 'Fault persists after tape repair → inspect sled drag and air separately. A dry tissue becoming wet identifies a possible joint leak; teacher disconnects/reseats and reprimes before retesting.')

add(3,'Time Five Delivery Cycles','Record three timed trials of five complete cargo-delivery cycles on the unchanged sled.','sled',
 'A baseline needs a repeatable definition. We will time the same task before and after a later mechanical change.',
 'Sled revision A, same paper cargo, stopwatch, ruler and trial sheet.',
 'G2’s START and DELIVERY lines define one cycle: sled begins at START, reaches the 20-mm line, then returns to START using input only. Five cycles make one timed trial.',
 ['Verify START-to-DELIVERY separation is 20 mm; use the same sled edge at both marks.', 'Reset input/output and check barrel witness line before each timed trial.'],
 ['Make table: trial | five cycles complete? | total time s | cycles/s | faults.', 'Practice one untimed trial. The aim is consistent complete travel, not forceful racing.'],
 ['Put cargo on deck. Operator holds input; timer watches the sled edge and calls “ready.”', 'Timer says “go” and starts clock as operator begins. Count a cycle only when sled reaches DELIVERY and returns to START.', 'Stop timer at the fifth return. If a cycle misses either mark, label trial invalid and record the missed endpoint.', 'Reset and repeat until there are three valid trials; retain invalid trials with reasons.', 'Rotate roles so each student operates and measures. Use gentle motion and the same cargo throughout.', 'Calculate 5 ÷ elapsed seconds for each trial. Calculate mean total time from the three valid trials.', 'Inspect the sled without modifying it. Mark the two side-fence top edges as tomorrow’s guide-rail reference.'],
 ['Three valid five-cycle trials; every endpoint reached. No direct pushing of output.', 'All rates use cycles/s, not cm/s. Record observed spread rather than reporting a single fastest run.'],
 ['Unchanged working sled revision A and a baseline timing record.', 'Three rates, mean time and exact cycle definition.'],
 'Rehearse endpoint visibility. A short strip of contrasting tape makes the sled edge easier to see; do not change travel to make timing easier.',
 'Demonstrate one complete cycle and one incomplete cycle. Say why an outstroke alone is not a complete out-and-back cycle.',
 'Watch one full trial per crew and confirm five returns. Record measuring independence separately from group performance.',
 'Counting only outstrokes → practice slowly. Very different times → inspect missed endpoints and role changes; keep honest variation. Stiction → repair first and clearly label a new baseline after repair.')

add(3,'Add Guide Rails and Retest the Sled','Add two fixed low guide rails beside the sled’s path, then repeat the same five-cycle timing test.','sled',
 'A controlled redesign changes one feature. Guide rails may improve alignment but can add friction; the test decides whether the change helps.',
 'Baseline sled/data, two 3 × 1-in card strips, 18 in tape, same cargo and stopwatch.',
 'G2 revision B adds two L-section rails. Fold each strip lengthwise into 1/2-in legs. Locate their vertical faces 1/8 in outside the sled’s left/right side edges across its full stroke; rails attach only to the base.',
 ['At START and DELIVERY, mark the sled’s side-edge positions on the base.', 'Offset each guide face 1/8 in outward from the widest side position. Start each 3-in rail level with the actuator-side deck edge at START; its length covers the 2-in deck plus 20-mm stroke.'],
 ['Draw both rails on revision B top view; keep revision A visible. Label 1/8-in side clearance.', 'Copy baseline mean time; prepare three new trials using the identical five-cycle definition.'],
 ['Cut/fold both rails into L sections.', 'Tape horizontal legs to the base outside the moving path; vertical legs face the sled sides. Keep tape edges off the sliding deck.', 'Move input slowly through the full stroke and return. The deck must not be pinched at either endpoint.', 'If a rail rubs, move that rail outward just enough to restore at least 1/8-in clearance; record its final location.', 'Run three valid five-cycle trials using the same cargo, endpoint marks and timing method as day 6.', 'Calculate mean time and percent time change relative to baseline. Record any cargo escape or missed endpoint separately.', 'Keep rails if they improve control without harmful binding. If worse, peel them off, restore revision A and record the rejected design.'],
 ['Only guide-rail configuration changes intentionally; load, travel and cycle count stay fixed.', 'Do not report improvement from an incomplete or faster-but-missed delivery. A worse result is usable engineering evidence.'],
 ['A tested rail revision, retained or removed with an evidence-based reason.', 'Before/after times, clearances, rates and annotated revision drawing.'],
 'Precheck rail clearance with the actual sled. Student choice is limited to retain/reject after the fixed baseline modification; this is not a new unspecified machine.',
 'Show where fixed rail tape goes and where it must not bridge to the sled. Model percent time reduction using the original baseline denominator.',
 'Ask students to distinguish a 20% time reduction from a 25% rate increase for a 20-to-16-second example. Both require a fixed task.',
 'New rail slows motion → inspect rubbing and record the tradeoff. No meaningful change → retain the data and explain the tie; do not optimize numbers by dropping valid trials.')

add(3,'Demonstrate the Delivery Machine','Hand over a working syringe sled and explain its motion, measured travel and tested revision.','sled',
 'A machine handover needs operating instructions, repeatability evidence and clear limits. An average alone cannot certify every delivery.',
 'Final sled, baseline/revision records, assembly drawing and same paper cargo.',
 'Final G2 drawing must label fixed barrel, moving plunger/sled, input/output, tube and retained rails. Circle the feature that changed.',
 ['Individually measure one actual 20-mm delivery stroke and the nozzle’s x position from datum A.', 'Review each measured travel; flag a stroke outside 20 ±2 mm even if the mean looks acceptable.'],
 ['Prepare a four-line operator card: load cargo; reset to START; move input until DELIVERY; pull input back to START. Add “stop if resistance rises.”', 'Choose one baseline and one revision result from actual notebook records, with units.'],
 ['Exchange machines and operator cards. New operator follows the card without coaching.', 'Perform three complete deliveries, recording each travel and any unclear instruction.', 'Return the machine. Owners fix one instruction or physical snag and repeat three deliveries.', 'Give a one-minute demonstration identifying how input motion travels through water to the output.', 'Each student reads a supplied assembly location, takes a tape/ruler reading and explains one rate calculation to the teacher.', 'Return plungers to reset marks and store connected pair in a tray; teacher drains/stores water systems according to the kit routine after the project.'],
 ['All three deliveries meet the classroom stroke check or remaining faults are named.', 'Claim only what was tested: a low-load water-powered sled, not a heated boat or measured force multiplier.'],
 ['A working delivery machine, operator card and accurate final assembly plan.', 'Individual math, measurement and plan-reading evidence plus the recorded redesign.'],
 'Prepare the individual-check roster and pair crews. Do not add a live pressure/load challenge during handover.',
 'Model identifying one real revised feature and citing its actual test record. Show why one failing stroke cannot be hidden by a mean.',
 'Look for a new operator who can complete the task from the card, plus each student’s independent measurement.',
 'New operator confused → improve the exact step or label, then repeat. Sled fails → record and diagnose before claiming handover complete.')

add(3,'Clinic: Restore a Shifted Sled Mount','Locate a 5-mm mounting error, restore the supplied assembly and repeat measured travel.','sled',
 'Fault finding combines reference locations with motion measurements. The intended fault today is a shifted barrel, not a mystery chosen during class.',
 'Working sled, ruler with mm, 12 in tape and original assembly drawing.',
 'G2 requires nozzle x=3 in, centerline y=3 in. Teacher shifts the fixed output barrel 5 mm sideways after loosening its saddles, leaving tube connected and unblocked.',
 ['Measure actual nozzle x/y and compare to the original witness line before motion.', 'Convert measured 5-mm shift to cm; keep location errors separate from stroke readings.'],
 ['Write symptom prediction: a sideways shift can skew the tab and make the sled rub.', 'Mark original and shifted axes on a small plan-view sketch.'],
 ['Inspect the deliberately shifted mount without operating it forcefully.', 'Explain which dimension disagrees with the plan. Partner checks the datum, not the answer.', 'Loosen saddle tape, restore nozzle and barrel to their original marks, then retape.', 'Check sled tab square to deck and clear of any retained guide rails.', 'Run three gentle 20-mm input strokes; record output travel and mount position each time.', 'Each student repeats one location measurement and one stroke measurement without partner help.'],
 ['Nozzle returns to marked x/y location within ±2 mm; output barrel remains fixed.', 'Three strokes recorded; missed travel triggers inspection of bubbles/drag rather than more force.'],
 ['A corrected mount and individual location/travel checks.', 'Fault → measurement → correction → retest record.'],
 'Prepare exactly the stated 5-mm side shift on each machine while at rest. Do not detach tubing or damage parts. This defined flex lesson can be used for extra measurement practice.',
 'Show location and travel as two different measurements with different references. Rehearse 2.7 cm = 27 mm.',
 'Students name the original datum and retain first readings. Each performs a fresh check after repair.',
 'Stroke still short → check fluid/start position after geometry is restored. Reading from the edge of a rail instead of the base datum → reset reference.')

add(4,'Build a Door-Open Light Signal','Make a card door that holds a clothespin switch open when shut; opening the door pulls out a card tongue and lights one 3-V lamp.','detector',
 'A control turns a physical event into an electrical signal. The door must operate the switch; a student’s hidden finger is not the detector.',
 '3-V two-AA switched holder, one 3-V lamp/holder, three alligator leads, one wooden spring clothespin, two 1 × 2-in foil strips, base 10 × 8 in, fixed wall 4 × 4 in, door 3 × 4 in, 1 × 3-in thin-card tongue and 24 in tape.',
 'J1 shows the only circuit: supply + → foil jaw A; foil jaw B → lamp A; lamp B → supply −. Foil surfaces touch when the tongue is withdrawn. A closed card door inserts the insulating tongue between them.',
 ['On the 10 × 8 base use the front-left corner as (0,0). Mark wall line y=3 in and hinge point (4,3). Mark tongue strip 1 × 3 in and fold 1 in from a short end.', 'Measure actual lead routes with a string along bends; record each run and 2-in classroom connection allowance separately from available lead length.'],
 ['Copy J1’s three connections with terminal labels. Trace the entire loop before attaching battery leads.', 'Sketch door shut/tongue inserted (lamp off) and door open/tongue out (lamp on).'],
 ['Tape the 4 × 4-in fixed wall upright along y=3 in, from x=0 to x=4; brace it with two small folded scrap triangles cut from a 2 × 2-in square.', 'Tape the 3 × 4-in door to the wall’s right vertical edge. Shut, it runs from x=4 to x=7 along y=3. It opens toward the FRONT of the base (smaller y).', 'Wrap one foil strip over the inside face of each clothespin jaw and around the outside for a clip contact. Tape foil backs securely; keep the two foil strips separate except at the jaw contact.', 'Glue is not required: put clothespin BEHIND the shut door, with jaws near (6 1/2,4 1/2) and handle extending toward the rear edge. Jaws face toward the door. Tape the lower handle to the base, keeping spring/upper handle free.', 'Fold the tongue 90 degrees at its 1-in mark. Tape the 1-in leg vertically to the BACK of the door near its free edge, center x=6 1/2, with the fold at base level. The 2-in leg projects BEHIND the shut door toward increasing y and enters the jaws. Opening the door toward the front withdraws it. Adjust jaw position slightly for an easy sliding fit.', 'With holder switched OFF, clip the three leads exactly as J1’s table states. Keep exposed clips apart except at intended terminals.', 'Teacher checks the loop. Turn holder ON. Tongue inserted should separate foil and turn lamp off; swinging door open should withdraw tongue so jaws close and lamp turns on.', 'Reset by gently opening the clothespin and reinserting tongue while closing the door. The opening action must trigger automatically; manual reset is allowed and stated.'],
 ['Open and reset the door five times. Record lamp OFF when shut and ON when opened in every trial.', 'Power OFF after the test. If battery or wire feels warm, switch off immediately and have teacher inspect the wiring.'],
 ['One working card-door/clothespin light detector with labeled terminals.', 'Schematic, route lengths and five OFF/ON test rows.'],
 'Prebuild the detector with actual clothespins and leads. Prepare seven matched kits and a completed model. Use foil jaw contacts and the specified filament lamp; no buzzer or bare-LED substitution is part of this recipe.',
 'Show the finished door action first. Explain that the card tongue is an insulator separating two conductors. Build the three-link circuit visibly with holder OFF, then demonstrate the teacher connection check.',
 'Look for automatic opening-trigger and explicit manual reset. Each student traces all three connections and measures one route.',
 'Always on → foil contacts touch around the tongue or leads bypass switch. Always off → foil faces not touching or lamp contact loose. Door buckles tongue → move clothespin rather than forcing the hinge.')

add(4,'Make the Door Trigger Reliable','Improve the same detector with a tongue guide and verify ten repeatable door-open signals.','detector',
 'Reliability is repeatable operation under a stated procedure. You will fix alignment and distinguish circuit connectivity from physical placement.',
 'Detector, one 3 × 1-in card strip, 12 in tape and the existing 1 × 3-in tongue.',
 'J1 schematic is unchanged. Add a loose paper guide loop around the tongue just before the clothespin jaws; it guides the tongue but must not contact foil electrically.',
 ['Measure tongue travel needed to fully clear the foil jaws. Mark that point with pencil.', 'Measure the clothespin jaw location from base datum and add it to the physical layout.'],
 ['Draw a separate schematic and base layout. The schematic shows connections; the layout shows actual component locations.', 'Make a ten-row table: tongue inserted OFF | door open ON | reset success.'],
 ['Switch holder OFF. Wrap the 3 × 1-in strip loosely around the tongue to make a sleeve; leave about 1/16 in sliding clearance.', 'Tape the sleeve ends to the fixed base/wall beside the clothespin, keeping it clear of jaws and foil.', 'Slide tongue through the sleeve into the open clothespin, then release jaws and close door.', 'Teacher checks connections remain unchanged. Turn holder ON and perform ten door-open/manual-reset cycles.', 'Swap operator after five. Record each state, not only an overall percentage.', 'If it catches, widen the sleeve or realign clothespin once. Repeat the full ten cycles and label the revision.', 'Power OFF and label final jaw/guide locations on the layout.'],
 ['Target ten correct OFF/ON pairs with no hidden contact assistance; record any failure.', 'Moving the clothespin changes layout coordinates but need not change the schematic connections.'],
 ['A detector with guided tongue and two distinct drawings.', 'Ten-trial reliability record before/after any adjustment.'],
 'Have spare tongue strips if creased. Show the loose guide and a deliberately overtight sample as a contrast during the demo.',
 'Demonstrate the same circuit with the lamp moved elsewhere on the base. Explain why its schematic connections are unchanged.',
 'Check ten actual cycles and both lamp states. Ask each student to locate a part on the layout and trace its connection on the schematic.',
 'Tongue jams → open the guide clearance and align it with jaws. Lamp flickers open → clean/flatten foil contact and inspect clips with power OFF.')

add(4,'Measure Voltage Across the Source and Lamp','At the teacher meter station, measure DC voltage across source and lamp, then diagnose one opened lamp connection.','circuit',
 'Voltage is a difference between two points. Correct probe placement helps trace an open path without guessing or rewiring randomly.',
 'Working detector; supervised digital multimeter with black lead in COM and red in V input; the demonstrated DC-voltage range above 3 V (typically 20 V on a manual-range meter).',
 'J marks source +/− and lamp A/B. For source voltage probe + and −; for lamp voltage probe A and B. Use the teacher’s labeled DC-V setup; do not move leads to current sockets.',
 ['Observe teacher confirm COM/V sockets, DC-V mode and suitable range on the actual meter.', 'Record source and lamp readings with tongue out (lamp on) and tongue inserted (lamp off); label both state and volts.'],
 ['Draw a voltmeter circle across source terminals, then a second example across lamp terminals. It bridges two test points; it is not inserted by removing a wire.', 'Prepare table: circuit condition | two test points | reading V | observation.'],
 ['Switch holder OFF while placing clips safely. Teacher checks that probes cannot bridge adjacent terminals.', 'Turn ON. Hold insulated probe handles and take the demonstrated source reading, then lamp A-to-B reading with tongue out.', 'Insert tongue and repeat lamp reading in OFF state. Do not infer every unseen circuit condition from this single reading.', 'Power OFF. Teacher removes the lead from lamp terminal A and parks the loose clip away from other conductors.', 'Power ON under supervision. Note lamp off; measure source then lamp using the same test points.', 'Power OFF, identify the disconnected terminal by tracing J, reconnect it and repeat the working lamp reading.', 'Return probes to station and store detector with holder OFF.'],
 ['Teacher directly observes each student’s correct DC-V mode and across-two-points connection.', 'Working source remains available during the open-lamp fault; actual readings depend on meter resolution and contact. No readings are invented when a station turn is pending.'],
 ['A restored working detector.', 'Actual state-labeled source/lamp voltage readings and identified open connection.'],
 'Set one protected teacher station and label the actual sockets/range using the meter manual. All crews continue detector layout/ten-cycle checks while awaiting a scheduled turn. The only fault is the removed lamp-A lead.',
 'Demonstrate across versus in-series using unplugged leads. State that a meter setting must be checked before touching a live test point.',
 'Record each student’s direct measurement separately. Readings need units and state; a bare number is insufficient.',
 'Negative reading → check probe polarity and explain the sign. No stable value → inspect probe contact and range. Never try a current mode to solve an uncertain voltage reading.')

add(4,'Measure Current in the Lamp Branch','At the supervised station, insert the meter into one break in the lamp circuit, record current, then restore the detector.','circuit',
 'Current measurement requires the circuit’s charge flow to pass through the instrument. This is a different connection from voltage measurement.',
 'Detector and teacher-operated meter station: fused current input/range suitable for the kit lamp rating, insulated leads and meter manual. Teacher makes and approves all current-mode wiring.',
 'J shows the break between switch output and lamp A. The current meter replaces that one connection in series. It never bridges supply + and −.',
 ['Teacher states the lamp rated current and the chosen meter input/range before the measurement.', 'Each student reads the stable current display with unit; teacher confirms A or mA and records the circuit condition.'],
 ['Draw the series insertion at the switch-to-lamp break. Draw the original direct lead beside it for restoration.', 'Work the supplied resistor example as a MODEL exercise; the filament lamp is not a constant 30-ohm resistor.'],
 ['Switch holder OFF and remove the original switch-to-lamp lead.', 'Teacher connects switch output to the meter current input and meter COM to lamp A, using the actual instrument’s fused rated input.', 'Teacher inspects the complete loop and selected current range, then permits holder ON with tongue out.', 'Each student reads and records current. Turn holder OFF before touching any wiring.', 'Teacher removes meter and restores the original switch-to-lamp lead. Return red meter lead to its V socket for storage.', 'Run three detector OFF/ON cycles to confirm restoration.', 'Compare the measured current with the stated lamp rating as an observation; do not force an Ohm-law match using an invented resistance.'],
 ['Every current reading includes unit and supervised series connection. No student experiments with meter sockets under power.', 'Detector works after meter removal; original loop is fully restored.'],
 ['Restored detector and an independently read current measurement.', 'Series-insertion sketch, A/mA conversion and separate supplied-resistor calculation.'],
 'Confirm meter fuse and current rating with the manual; use only a rated low-voltage lamp circuit. Teacher controls setup and wiring changes at one station. If suitable meter is absent, this lesson remains pending while students complete a defined detector reliability/diagram practice; it is not signed off.',
 'Show how removing one wire creates two points for a SERIES insertion. Contrast with yesterday’s voltage probes across the lamp.',
 'Observe each student identify series location and read units. Do not award hands-on measurement from a worksheet alone.',
 'Unexpected zero → power OFF and inspect the open series loop/fuse using the manual. Never move to a larger source or bypass the fuse. Incorrect reading units → inspect display annunciator before converting.')

add(4,'Wire Two Independently Lit Rooms','Build a two-room card model on an 8 × 6-in base; wire each 3-V lamp through its own switch in parallel.','circuit',
 'Independent controls require independent branches sharing a source. Testing all four switch states proves more than simply lighting both lamps.',
 '3-V holder, two 3-V lamps/holders, two SPST switches, eight alligator leads, base 8 × 6 in, two outer walls 8 × 3 in, three wall blanks 6 × 3 in and 36 in tape. Retain door detector separately for next lesson.',
 'J connection table: +→S1-1→S1-2→L1-A→L1-B→−; second branch +→S2-1→S2-2→L2-A→L2-B→−. Each arrow between components is a lead; the switch and lamp each have two terminals.',
 ['Mark base center divider x=4 in from left datum. Mark lamp centers (2,3) and (6,3) in.', 'Mark S1 at (2,1) and S2 at (6,1). Measure actual lead routes; no cutting commercial leads.'],
 ['Copy both branches with labels. Make state table S1/S2: OFF/OFF, ON/OFF, OFF/ON, ON/ON.', 'Draw physical layout with the specified centers and battery just outside the rear wall.'],
 ['Cut base and wall blanks. Tape 8 × 3-in front/rear walls upright on the base.', 'Dry-fit and trim left/right/divider 6 × 3-in blanks to the gap between front/rear walls. Tape outside walls at base edges and divider centered on x=4.', 'Tape lamp holders and switches at their marked positions. Keep terminals accessible; route leads over the open wall tops.', 'Holder OFF: connect + to S1-1, S1-2 to L1-A, L1-B to −. These are the first branch’s three leads.', 'Connect + to S2-1, S2-2 to L2-A, L2-B to − with three more leads. Share the marked supply terminals without letting + clips touch − clips.', 'Teacher checks branches and combined lamp rating. Turn holder ON and test all four states in order.', 'Correct any misconnection with holder OFF; repeat all four states. Label rooms 1/2 and lamps L1/L2.'],
 ['00: neither lamp; 10: L1 only; 01: L2 only; 11: both. Repeat the four-state sequence three times.', 'Changing one switch must not change the other lamp. Record all twelve checks.'],
 ['Two-room model with independently controlled lamps and accessible wiring.', 'Matched schematic/layout and twelve state-test results.'],
 'Check the two-lamp load against battery holder/switch ratings using kit information. Provide spare leads. The model is open-top and has no need for mains wiring.',
 'Build one branch, then trace the second from the same + to the same −. Demonstrate that placing S2 in a shared return would break independence.',
 'Have each student trace and measure one branch. Verify four states rather than accepting a photograph of both lamps on.',
 'Both follow one switch → switch sits in a shared segment; restore separate branches. One never lights → power OFF and trace its three leads/holder contacts. Warm supply → OFF immediately and teacher checks for a bypass short.')

add(4,'Add the Door Signal to Room Two','Replace room 2’s manual switch with the clothespin door detector; room 1 remains independently switched.','detector',
 'A useful control responds to a condition. We will make room 2’s light act as a door-open signal without changing room 1.',
 'Two-room model, retained clothespin/foil switch, one 3 × 3-in card door, 1 × 3-in tongue, guide strip and 18 in tape. No added electrical load is required.',
 'Required revised branch: +→clothespin jaw A; jaw B→L2-A; L2-B→−. Room 1’s S1/L1 branch is unchanged. S2 is removed and stored, not left ambiguously in series.',
 ['Mark a 2 1/2 × 2 1/2-in door opening in room 2’s front wall, right jamb 1/2 in from the right outside corner; mark the left jamb 2 1/2 in farther toward the center divider.', 'Measure tongue travel and locate the clothespin INSIDE room 2 so a shut door inserts a tongue pointing into the room; keep clips accessible from the open top.'],
 ['Draw the new room 2 schematic with detector contacts replacing S2. Cross out S2 on the revision, not on the original record.', 'State table is now S1 OFF/ON × door SHUT/OPEN; predict all four outputs.'],
 ['Power OFF and remove room 2’s two switch leads from S2.', 'Cut the door opening out of room 2’s front wall; preserve the surrounding wall. Tape a 3 × 3-in door over it along the left jamb to form an outward-opening hinge.', 'Fold the 1 × 3-in tongue 1 in from a short end. Tape the 1-in leg vertically INSIDE the lower free edge of the door, fold at base level, so its 2-in leg points into room 2. Put clothespin inside the room with jaws facing the front wall and handle toward the rear. Shut door inserts tongue; outward opening withdraws it.', 'Attach a loose guide loop just before the jaws, using the earlier detector method.', 'Connect supply + to jaw A and jaw B to L2-A; keep L2-B return to −. Remove unused S2 from the model.', 'Teacher checks circuit. Power ON and test four states: S1 off/door shut, S1 on/shut, S1 off/open, S1 on/open.', 'Repeat each state three times. Reset the door by opening clothespin to reinsert tongue. Power OFF for storage.'],
 ['L1 follows only S1; L2 follows door position (shut OFF, open ON). All twelve state checks recorded.', 'Door opens without snagging wires; reset method is printed on the model.'],
 ['A two-room model with room 1 light switch and room 2 door-open signal.', 'Revised schematic, layout and four-state table.'],
 'Precheck cut opening fits the model’s actual room-2 width. This extension reuses the existing lamp and detector; no fan, buzzer or additional choice is required.',
 'Show exactly which two S2 leads move to the two foil contacts. Point out that the detector replaces a switch, not a lamp or return path.',
 'Observe independence and automatic door-open trigger. Each student identifies the changed branch on the schematic.',
 'Room 1 changes with door → detector accidentally installed in shared supply/return; restore J branch separation. Tongue snags → guide alignment, not electrical rewiring, is the needed repair.')

add(4,'Make an Operating Schedule and Energy Estimate','Use the actual model to demonstrate two room-use schedules, then calculate their energy with supplied lamp-power values.','energy',
 'Energy depends on both power and time. A useful schedule keeps necessary functions while avoiding unnecessary run time.',
 'Working model, timer, two 3 × 5-in schedule cards and notebook. Use supplied calculation value 0.30 W per lamp; label it ASSUMED, not measured.',
 'K: power W × time h = energy Wh; divide Wh by 1,000 for kWh. Keep each branch’s operating interval separate.',
 ['Demonstrate schedule A for 60 seconds: S1 on and door open throughout; both lamps on.', 'Demonstrate schedule B for 60 seconds: S1 on throughout; door open for the first 15 seconds, then shut. Record actual state timings.'],
 ['Calculation schedule A represents both lamps on for 4 h. B represents L1 on 4 h and L2 on 1 h. The classroom minute is a compressed demonstration, not four hours of measured energy.', 'Calculate both using the supplied 0.30-W value and compare Wh.'],
 ['Write schedule A and B on separate cards with all switch/door instructions.', 'Run A, then power OFF while preparing the reset. Run B and have another crew observe the changing lamp states.', 'Calculate A: 2 × 0.30 × 4. Calculate B: 0.30 × 4 + 0.30 × 1.', 'Find saved Wh and percent reduction relative to A. Calculate sample energy-only cost at $0.25/kWh.', 'Attach schedule B beside the control and demonstrate it once more to a new operator.', 'Store the model with holder OFF; do not leave it running for the imagined four-hour schedule.'],
 ['Model demonstrates the stated switching sequence; calculations explicitly use assumed 0.30 W and represented hours.', 'Energy cost is not battery purchase cost or a battery-runtime prediction.'],
 ['A model with a usable schedule card and verified state sequence.', 'Two energy budgets, saved Wh and labeled assumptions.'],
 'Use supplied values for every crew so equipment variation does not disguise the arithmetic. No generator kit is needed. Keep actual observed seconds separate from represented hours.',
 'Model one branch calculation and explain why watts and watt-hours differ. Show A=2.4 Wh, B=1.5 Wh, saving0.9 Wh (37.5%).',
 'Look for both branches in the budget and kWh conversion before multiplying by the sample tariff. Each student calculates independently.',
 'Student uses 60 seconds as 60 hours → separate demonstration column from calculation schedule. Cost too large → check Wh-to-kWh division by 1,000.')

add(4,'Find an Open Return and Hand Over the Controls','Diagnose a removed L2 return lead, repair it, and repeat all four control states before handover.','circuit',
 'A specific symptom should lead to a specific branch check. The final handover proves both the repaired function and unaffected function still work.',
 'Final model, revised schematic, twelve-check sheet and existing leads. Teacher removes L2-B return at the lamp while holder is OFF and parks the clip safely.',
 'Use the final schematic: S1 controls L1; detector controls L2. The selected fault is an OPEN L2 return, not a short or an unspecified hidden defect.',
 ['Inspect all actual connection points against the revised schematic and label the disconnected terminal.', 'Measure one route from component to supply along its actual bends; add the supplied 2-in planning allowance.'],
 ['Predict outputs for all four S1/door states with the open L2 return.', 'Write diagnosis before repair: which branch cannot complete a path and which should still function.'],
 ['Teacher prepares the one stated open connection with power OFF.', 'Power ON briefly and observe four states; record symptoms without moving clips.', 'Power OFF. Trace L2’s entire path and point to the missing return link on the drawing.', 'Reconnect L2-B to supply −; teacher checks exposed clips are separated.', 'Power ON and repeat all four S1/door states three times. Record each of twelve checks.', 'Give a one-minute handover with door-reset and power-off instructions. Each student performs an individual schematic/measurement/math check.', 'Power OFF and inventory lamps, switches, leads and cells.'],
 ['L1 remains independent and L2 responds to door after repair; all twelve checks documented.', 'Fault report names the open return and evidence rather than “the battery was bad” without a test.'],
 ['A working, inspected control model and short operator note.', 'Individual check record plus fault/repair/retest evidence.'],
 'Prepare only the specified L2-B open fault. Use no current-meter faults or deliberate shorts. Keep old manual S2 labeled in the kit.',
 'Trace one complete branch aloud, then model predicting which output is affected by an open return.',
 'Record measuring, plan reading and math separately. A student who did not independently demonstrate a skill remains not observed and gets a focused retry.',
 'Both lamps off → inspect shared source switch/connections, not the intended single-branch fault. Repair fixes one state only → repeat full table and inspect trigger geometry.')

add(4,'Clinic: Lay Out Mounting Centers and Trace a Branch','Make the four-center paper template and use it to explain physical location versus electrical connection.','template',
 'Installers need both a layout and a schematic. One locates a component; the other tells what connects to it.',
 'One 8 1/2 × 5 1/4-in paper sheet per student, completed model and final schematic. No drilling.',
 'C’s four centers are 3/4 in from adjacent edges. Label them P1–P4 clockwise starting lower-left. They are paper mounting references, not new live connection points.',
 ['Individually mark x=3/4 and 7 3/4; y=3/4 and 4 1/2 in from lower-left datum.', 'Check one actual model component’s x/y location and one routed lead length.'],
 ['Draw light coordinate guides and mark four crosses. Copy actual component coordinates to the model layout.', 'Trace the room-2 electrical path in a different notebook sketch using terminal names.'],
 ['Cut the paper outline and mark all four centers without teammate assistance.', 'Exchange and inspect offsets within ±1/16 in; retain corrections beside original marks.', 'Put template beside the actual model, not on live terminals. Explain which measurement method transfers to component placement.', 'Power OFF and trace room 2 from supply + through detector/lamp to −. Read each terminal label aloud.', 'Replace one worn layout label and retest the four states after teacher check.', 'Complete a fresh independent route subtraction and show the teacher one center measurement.'],
 ['Four located centers meet the paper tolerance; model layout has actual coordinates.', 'Student chooses layout for position and schematic for connectivity.'],
 ['An individual mounting template and corrected model documentation.', 'Separate physical-location and circuit-path explanations.'],
 'Use this defined flex lesson for measurement/plan practice. Prepare a large C drawing and model with intact wiring; no new surprise fault is needed.',
 'Ask “Where is it?” with the layout, then “What connects to it?” with the schematic; demonstrate one of each.',
 'Each student performs their own center mark and branch trace. Do not accept a partner’s completed template.',
 'Schematic used to measure wire length → use actual physical route. Mixed inch/mm coordinates → relabel and convert before comparison.')

add(4,'Prepare the Working Controls Exhibition','Prepare the completed two-room control model for a two-minute demonstration with one drawing and one real test record.','circuit',
 'A vocational demonstration must show a function and explain evidence. Today’s required exhibit is the control model, so every crew knows what to prepare.',
 'Final two-room model, final schematic/layout, state-test and repair records, one 3 × 5-in operator card and 12 in repair tape.',
 'Use the final control schematic with the door detector replacing S2. Keep the physical layout beside it and circle the actual repair/revision.',
 ['Individually remeasure one component location or lead route using its original datum.', 'Repeat all four S1/door states and record actual outputs before preparing the demonstration.'],
 ['Write a two-minute sequence: 20 s purpose; 40 s four states; 30 s drawing/measurement; 30 s repair and evidence.', 'Choose one real calculation from your notebook with given values, units and result; prepare to explain it without a teammate.'],
 ['A new partner operates the model using only its card. Mark any unclear instruction or snag.', 'Power OFF before repair. Fix that one physical issue or rewrite the exact unclear instruction; if none was found, improve a missing terminal label.', 'Repeat all four states after the change.', 'Put model, schematic, layout and one test record on the table. A slideshow is not required.', 'Rehearse the two-minute sequence. Each student operates and explains one distinct skill; trio roles rotate.', 'Label setup/reset/power-off steps on the operator card. Store the checked exhibit with holder OFF.'],
 ['New operator can reset door and demonstrate independent branches from the card.', 'Each student can show their own measured value and calculation; a decorative poster does not replace either.'],
 ['A ready two-room control exhibit with operator card and evidence.', 'One corrected detail and a rehearsed demonstration.'],
 'Set up seven exhibition spots with table space and identify visiting crew pairs. The required exhibit is the completed controls project; earlier projects can be displayed alongside only after this is ready.',
 'Give a two-minute model demonstration showing the object first, then one drawing and one calculation. Keep the evidence concise.',
 'Check every crew has a real functioning exhibit or a clearly documented fault under repair. Observe each student’s distinct contribution.',
 'Exhibit unreliable → use work time on the actual fault, not presentation decoration. Student reads a memorized claim → ask them to locate and remeasure the feature.')

add(4,'Demonstrate, Inspect and Complete Individual Checks','Run the control exhibition and complete each student’s independent trades-math, measuring and plan-reading check.','circuit',
 'A finished course should show skills each person can perform. Team products provide the context; individual demonstrations establish the learning.',
 'Prepared control exhibit, operator card, notebook and final drawings; teacher roster for four separate skill checks.',
 'Use the final schematic to trace one complete branch and the layout to locate a component from the stated datum. The supplied tolerance problem is a separate inspection exercise.',
 ['Each student measures one assigned component position or lead route without partner help, naming endpoints and units.', 'Compare measured value with the student’s final drawing and record signed difference.'],
 ['Mark where your notebook shows an actual repair, retest and calculation.', 'Read the supplied tolerance transfer problem independently; state both limits before deciding acceptance.'],
 ['Set up exhibit with power OFF; teacher inspects connections before operation.', 'Demonstrate four control states to the visiting crew. Rotate operator, drawing explainer and inspector roles.', 'Visitor records one specific observation: correct function, unclear step or located mismatch.', 'Power OFF, correct that exact issue if present and repeat affected states; if none, complete the full final four-state check.', 'At the teacher station each student: traces one branch; measures a physical dimension; solves the tolerance calculation; explains a named repair and retest.', 'Record any still-missing skill as pending and complete a focused retry while other students inventory and store equipment.', 'Power OFF, separate cells only under the kit storage routine, count parts and submit the single individual app response.'],
 ['All four control states demonstrated or the remaining fault precisely identified.', 'Teacher records math, measuring, plan interpretation and build/revision separately for every student.'],
 ['Completed demonstration, stored kit and individual vocational-skills record.', 'Final notebook contains drawing, measurement, calculation and real revision evidence.'],
 'Use a 15-student roster with four columns. Schedule brief individual checks throughout Make/Test, about 3 minutes each while other crews exhibit or retry. Keep the physical measurement prompt fresh for each student.',
 'Show the four things the individual check requires. Model naming a datum and units before reading the tape. Explain that a missing observation is a next check, not automatic crew credit.',
 'Use independent / with cue / not observed and record the actual evidence. Offer one focused retry without supplying the answer.',
 'Time runs out for a student → record the specific remaining check and schedule its completion; do not infer mastery. Product fails → a sound diagnosis is valid evidence but does not become a passing function test.')

# Keep independent transfer checks coherent with the now-fixed construction route.
DAYS[21]['example']=('Calculate the delivery machine’s cycle rate.','5 complete cycles in 25 s = 0.20 cycles/s.','A cycle includes travel from START to DELIVERY and back to START; one outward stroke is not a cycle.')
DAYS[21]['exit']='A delivery machine completes 5 full cycles in 25 s. Calculate its rate in cycles/s. Name the drawing marks that define a complete cycle and cite your actual test record.'
DAYS[21]['key']='0.20 cycles/s. START → 20-mm DELIVERY line → START defines one complete cycle. Actual trial data must come from the student’s notebook.'
assert len(DAYS)==36
assert [sum(d['project']==p for d in DAYS) for p in range(1,5)]==[6,10,9,11]
assert {k:sum(d['kind']==k for d in DAYS) for k in ('core','flex','exhibition')}=={'core':30,'flex':4,'exhibition':2}
